{
  "findings": [
    {
      "check_id": "CKV_AZURE_117",
      "title": "Storage account network rules allow all traffic by default",
      "resource": "azurerm_storage_account_network_rules.notification_storage_rules",
      "severity": "CRITICAL",
      "explanation": "The default_action is set to 'Allow', allowing all traffic to the storage account by default, which is a significant security risk."
    },
    {
      "check_id": "CKV_AZURE_36",
      "title": "Storage account network rules allow traffic from localhost IP",
      "resource": "azurerm_storage_account_network_rules.notification_storage_rules",
      "severity": "MEDIUM",
      "explanation": "The ip_rules include '127.0.0.1', which is a localhost IP and not a valid rule for restricting access to the storage account."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account_network_rules\" \"notification_storage_rules\" {\n  storage_account_id = azurerm_storage_account.notification_storage.id\n  default_action     = \"Deny\"\n  ip_rules           = []\n  bypass             = [\"Metrics\", \"Logging\", \"AzureServices\"]\n}",
  "fix_summary": "Changed default_action to 'Deny' to block all traffic by default, removed '127.0.0.1' from ip_rules as it's not a valid restriction, and added 'AzureServices' to bypass to allow Azure services to access the storage account."
}
